fn solve(a: i8, b: i8, k: i8) -> (i8, i8) {
    // Determine how many we can remove from the first pile
    let remove_from_a = a.min(k);
    let a_remaining = a - remove_from_a;

    // Subtract the removals from k to see what's left for pile B
    let k_remaining = k - remove_from_a;
    let remove_from_b = b.min(k_remaining);
    let b_remaining = b - remove_from_b;

    (a_remaining, b_remaining)
}

fn main() {
    // Example usage:
    assert_eq!(solve(5, 3, 2), (3, 3));  // remove 2 from pile A
    assert_eq!(solve(5, 3, 6), (0, 2));  // remove 5 from A, 1 from B
    assert_eq!(solve(2, 2, 5), (0, 0));  // remove all from both
    println!("All tests passed!");
}